assert sys.flags.isolated and sys.flags.no_site
root=Path(__file__).resolve().parents[2];p=root/'research/nine-sharing-sign16-aux-from-seed-check';draft=root/'research/nine-sharing-sign16-aux-from-seed-draft';sha=lambda q:hashlib.sha256(q.read_bytes()).hexdigest();run=p/'run.py';m=p/'source-manifest.json';assert sha(run)=='65021ac877f4f8c5351c0525193fbf02737aba2cd7b995075312e5b9a19d7bf1' and sha(m)=='4c0d67ad697dfc4f4c62f9a3e33c57f1b8beabb9a82a1e97b6985eb961df0d33';row,=json.loads(m.read_text())['rows'];name='Sign16AuxFromSeed';src=p/'src/DiophantineConsistency'/(name+'.lean');s=src.read_text();assert sha(src)==sha(draft/(name+'.lean'))==row['source_sha256'] and row['module']=='DiophantineConsistency.'+name and re.findall(r'^import ([A-Za-z0-9_.]+)$',s,re.M)==row['imports']==['DiophantineConsistency.Sign16InnerFromSeed','DiophantineConsistency.Sign16AbsDiffIngredient'];assert not re.search(r'(?m)^\s*(axiom|opaque)\b|\b(sorry|admit)\b',s)
for t in ('theorem auxiliary_of_seed','(hp0 :','(hp1 :','(hp2 :','(hp3 :','(hb : 0 < beta) (hMC : MC < beta) (hMF : MF < 2 * beta)','(hz : InternalZero (seed p) v)','let u := absdiff (f*f*c*T) (f*f*r+c)','S*S*u*u + y*y = 1 + S*S*y*y','Sign16InnerFromSeed.inner_of_seed','Sign16RowPremises.signed_na_of_seed','Sign16AbsDiffIngredient.auxiliary_norm_of_signed'):assert t in s
r=run.read_text();survey=p/'provider-survey.py';assert sha(survey)=='dc7f06fd5a770a2bbbbf0457c145dc99fb0a0099c1d035f7f5d56b2b1ab08f5c' and "if local=='Sign16AbsDiffIngredient':" in r and "for rel,rec in survey['extra'].items():" in r and "'-M2800'" in r and 'rss_limit=4*1024**3,mem_floor=10*1024**3,seconds=120,interval=.1' in r
for label,pin in [('inner-from-seed','1d32691192c25314dad6fec4a2255533f7e119e4998328b7a8b793417d4ebbc4'),('absdiff-ingredient-retry01','347a359092731096892f9f0d0394296d3e717e950626c0b67d0749a4439ec8aa')]:
 check=root/('reviews/nine-sharing-sign16-'+label+'-terminal-independent/check.py');assert sha(check)==pin;subprocess.run([sys.executable,'-I','-S','-B',str(check)],capture_output=True,check=True,timeout=120)
z=subprocess.run([sys.executable,'-I','-S','-B',str(survey)],capture_output=True,text=True,check=True,timeout=120);surveydata=json.loads(z.stdout);assert surveydata['status']=='PASS' and len(surveydata['extra'])==108 and surveydata['object_sha256']=='751bde0ac12dea2d899dfb1f5d34103e0d6d444399701bed769eb65df99c26e8'
x=subprocess.run([sys.executable,'-I','-S','-B',str(run),'--preflight'],capture_output=True,text=True,timeout=180);assert x.returncode==0 and not x.stderr and json.loads(x.stdout)['status']=='PASS_NO_LEAN_PREFLIGHT'
print(json.dumps({'status':'PASS_PRELAUNCH','runner_sha256':sha(run),'extra_overlays':108,'overlap':surveydata['overlap_count'],'scope':'conditional auxiliary norm from seed, no deleted V witness; remaining norms and lift unproved'},indent=2,sort_keys=True))
